'use client';

import { useEffect } from 'react';
import { KDSHeader } from '@/modules/kds/components/KDSHeader';
import { KDSColumn } from '@/modules/kds/components/board/KDSColumn';
import { useKDSStore } from '@/modules/kds/store/kdsStore';
import { useShallow } from 'zustand/react/shallow';

import { KitchenStage } from '@/modules/kds/types/kds';

export default function KDSMasterPage() {
    // We only need to know if there are any orders at all for the empty state.
    const hasOrders = useKDSStore(useShallow((state) => Object.keys(state.orders).length > 0));
    const { addOrUpdateOrder } = useKDSStore();

    useEffect(() => {
        if (!hasOrders) {
            // POS Pickup
            addOrUpdateOrder({
                id: 'm-1', orderNumber: '1001', order_source: 'POS', fulfillment_type: 'PICKUP',
                createdAt: new Date().toISOString(), stage: 'ACCEPTED', prepTimeMinutes: 10, estimatedReadyTime: '12:00',
                isDelayed: false, trackingToken: 't1', items: [{ name: 'Burger', modifiers: [] }]
            });
            // Online Delivery
            addOrUpdateOrder({
                id: 'm-2', orderNumber: '1002', order_source: 'ONLINE', fulfillment_type: 'STORE_DELIVERY',
                createdAt: new Date().toISOString(), stage: 'PREPARATION', prepTimeMinutes: 15, estimatedReadyTime: '12:15',
                isDelayed: false, trackingToken: 't2', items: [{ name: 'Pizza', modifiers: [] }]
            });
            // Kiosk Delivery
            addOrUpdateOrder({
                id: 'm-3', orderNumber: '1003', order_source: 'KIOSK', fulfillment_type: 'UBER_DIRECT_DELIVERY',
                createdAt: new Date().toISOString(), stage: 'CUTTING', prepTimeMinutes: 20, estimatedReadyTime: '12:20',
                isDelayed: false, trackingToken: 't3', items: [{ name: 'Salad', modifiers: [] }]
            });
        }
    }, [hasOrders, addOrUpdateOrder]);

    const stages: { id: KitchenStage; title: string }[] = [
        { id: 'ACCEPTED', title: 'Accepted' },
        { id: 'PREPARATION', title: 'Preparation' },
        { id: 'CUTTING', title: 'Cutting' },
        { id: 'READY', title: 'Ready' }
    ];

    return (
        <div className="flex flex-col h-screen overflow-hidden bg-slate-900 shadow-2xl">
            <KDSHeader />

            <main className="kds-board">
                {stages.map((stage) => (
                    <KDSColumn
                        key={stage.id}
                        title={stage.title}
                        stage={stage.id}
                    />
                ))}

                {!hasOrders && (
                    <div className="absolute inset-0 flex items-center justify-center pointer-events-none">
                        <div className="text-slate-500 font-black uppercase tracking-[0.2em] animate-pulse">
                            Waiting for orders...
                        </div>
                    </div>
                )}
            </main>
        </div>
    );
}
